{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Atazanavir, a structurally related HIV protease inhibitor with a similar peptidomimetic scaffold, has an absolute oral bioavailability of 68% (57–80%) in humans, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Darunavir, another HIV protease inhibitor sharing the hydroxyethylene core and carbamate functionality, has an oral bioavailability of 37% when given alone, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Amprenavir, a related HIV protease inhibitor, is orally bioavailable at >70% in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "KNI-272, a peptidomimetic protease inhibitor with a hydroxyethylene isostere, has an absolute oral bioavailability of about 29.6% in fasting patients, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Lopinavir, the closest retrieved analogue, is reported to have low oral bioavailability due to extensive CYP3A4 first-pass metabolism and P-gp efflux; this is the main contradictory evidence, but its transfer is weakened because the query is itself a potent CYP3A/P-gp inhibitor with a different absorption-metabolism balance.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is ritonavir, an HIV protease inhibitor. Multiple related protease inhibitors with measured oral bioavailability (atazanavir 68%, darunavir 37%, amprenavir >70%, KNI-272 ~30–55%) support F ≥ 20%. The closest analogue lopinavir is reported low, but its low bioavailability is mechanistically tied to extensive CYP3A/P-gp clearance and is less transferable to ritonavir, which inhibits these pathways. Overall, high oral bioavailability at the 20% threshold is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query molecule itself is present in the supplied evidence set.",
    "Lopinavir, the closest analogue, is reported only qualitatively as low/poor without a numeric F value, making threshold comparison uncertain.",
    "Some supportive records are not explicitly absolute bioavailability measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

